+import React, { useEffect, useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Field from '../../elements/Field';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [displayName, setDisplayName] = useState(device.display_name);
+    const [isEditing, setIsEditing] = useState(false);
+    const [newName, setNewName] = useState('');
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+
+    useEffect(() => {
+        setDisplayName(device.display_name);
+    }, [device.device_id, device.display_name]);
+
+    const onRename = () => {
+        setNewName(displayName ?? '');
+        setError(undefined);
+        setIsEditing(true);
+    };
+
+    const onCancel = () => {
+        setError(undefined);
+        setIsEditing(false);
+    };
+
+    const onSave = async (event?: React.SyntheticEvent) => {
+        event?.preventDefault();
+        if (isSaving) return;
+        if (newName === displayName) {
+            setIsEditing(false);
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, newName);
+            setDisplayName(newName);
+            setIsEditing(false);
+        } catch (error) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (isEditing) {
+        return <form className='mx_DeviceDetailHeading_edit' data-testid='device-detail-heading-edit' onSubmit={onSave}>
+            <Field
+                label={_t('Session name')}
+                type='text'
+                value={newName}
+                maxLength={100}
+                autoComplete='off'
+                autoFocus
+                disabled={isSaving}
+                onChange={(event: React.ChangeEvent<HTMLInputElement>) => setNewName(event.target.value)}
+                data-testid='device-detail-heading-input'
+            />
+            <p>{ _t("A session's name is visible to people you communicate with.") }</p>
+            { error && <p role='alert' data-testid='device-detail-heading-error'>{ error }</p> }
+            <div className='mx_DeviceDetailHeading_actions'>
+                <AccessibleButton kind='primary'
+                    onClick={onSave}
+                    disabled={isSaving}
+                    data-testid='device-detail-heading-save'>
+                    { _t('Save') } { isSaving && <Spinner w={16} h={16} /> }
+                </AccessibleButton>
+                <AccessibleButton kind='link_inline'
+                    onClick={onCancel}
+                    disabled={isSaving}
+                    data-testid='device-detail-heading-cancel'>
+                    { _t('Cancel') }
+                </AccessibleButton>
+            </div>
+        </form>;
+    }
+
+    return <div className='mx_DeviceDetailHeading_read' data-testid='device-detail-heading-read'>
+        <Heading size='h3'>{ displayName ?? device.device_id }</Heading>
+        <AccessibleButton kind='link_inline' onClick={onRename} data-testid='device-detail-heading-rename'>
+            { _t('Rename') }
+        </AccessibleButton>
+    </div>;
+};
